<script setup lang="ts">import { computed,ref } from 'vue';import { useRoute,useRouter } from 'vue-router';import { ElSwitch,ElSlider,ElInput,ElButton } from 'element-plus';import { useSettingsStore } from '../stores/settings.store';import { useCalendarStore } from '../stores/calendar.store';import { useRadioStore } from '../stores/radio.store';import { useRadioSchedulesStore } from '../stores/radioSchedules.store';import { createBackup,downloadBackup,restoreBackup } from '../services/backup';import { requestPersistentStorage } from '../services/storage/db';const s=useSettingsStore(),c=useCalendarStore(),radio=useRadioStore(),radioSchedules=useRadioSchedulesStore(),router=useRouter(),route=useRoute();const section=ref(String(route.query.section||'appearance')),calName=ref('Personale'),calUrl=ref(''),persistent=ref<boolean>(),scheduleStation=ref(''),scheduleStart=ref('08:00'),scheduleEnd=ref('10:00'),scheduleDays=ref([1,2,3,4,5]);function applyTheme(){const t=s.data.theme==='auto'?(matchMedia('(prefers-color-scheme: light)').matches?'light':'dark'):s.data.theme;document.documentElement.dataset.theme=t}const sections=[['appearance','Aspetto'],['time','Ora e data'],['weather','Meteo'],['calendar','Calendario'],['radio','Radio'],['data','Dati'],['system','Sistema'],['about','Informazioni']] as const;async function addCal(){if(!calUrl.value.trim())return;await c.addSource(calName.value,calUrl.value);calUrl.value=''}async function addSchedule(){if(!scheduleStation.value||!scheduleDays.value.length)return;await radioSchedules.add({stationId:scheduleStation.value,start:scheduleStart.value,end:scheduleEnd.value,days:[...scheduleDays.value],enabled:true})}async function backup(){downloadBackup(await createBackup())}async function importBackup(ev:Event){const input=ev.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{await restoreBackup(JSON.parse(await file.text()));location.reload()}catch(e){alert(e instanceof Error?e.message:'Backup non valido')}finally{input.value=''}}async function geo(){navigator.geolocation?.getCurrentPosition(p=>{s.data.latitude=p.coords.latitude;s.data.longitude=p.coords.longitude;s.data.weatherEnabled=true},()=>{})}async function persist(){persistent.value=await requestPersistentStorage()}</script><template><div class="screen-page"><div class="screen-shell settings"><header class="screen-header"><button class="icon-btn" @click="router.push('/')">←</button><div><div class="eyebrow">Istante 4</div><h1 class="screen-title">Impostazioni</h1></div></header><aside><button v-for="x in sections" :key="x[0]" :class="{active:section===x[0]}" @click="section=x[0]">{{x[1]}}</button></aside><section class="panel glass"><template v-if="section==='appearance'"><h2>Aspetto</h2><label class="row"><span>Sfondo fotografico</span><ElSwitch :model-value="s.data.background==='photo'" @update:model-value="v=>s.data.background=v?'photo':'gradient'"/></label><label class="field"><span>Tema</span><select v-model="s.data.theme" @change="applyTheme"><option value="auto">Automatico</option><option value="dark">Scuro</option><option value="light">Chiaro</option></select></label><label class="field"><span>Scala interfaccia</span><ElSlider v-model="s.data.uiScale" :min=".85" :max="1.25" :step=".05"/></label></template><template v-else-if="section==='time'"><h2>Ora e data</h2><label class="row"><span>Formato 24 ore</span><ElSwitch v-model="s.data.clock24"/></label><label class="row"><span>Mostra secondi</span><ElSwitch v-model="s.data.showSeconds"/></label></template><template v-else-if="section==='weather'"><h2>Meteo</h2><label class="row"><span>Mostra meteo</span><ElSwitch v-model="s.data.weatherEnabled"/></label><p class="muted">La posizione resta memorizzata sul dispositivo. Il browser chiederà il permesso solo quando lo richiedi.</p><ElButton @click="geo">Usa posizione attuale</ElButton><div v-if="s.data.latitude" class="muted">{{s.data.latitude.toFixed(3)}}, {{s.data.longitude?.toFixed(3)}}</div></template><template v-else-if="section==='calendar'"><h2>Calendario</h2><p class="muted">I calendari remoti vengono salvati come <b>link ICS</b>, non come file. Nel backup il link resta quindi utilizzabile anche su un altro dispositivo.</p><div class="calendar-add"><ElInput v-model="calName" placeholder="Nome calendario"/><ElInput v-model="calUrl" type="password" show-password placeholder="https://…/calendar.ics"/><ElButton type="primary" @click="addCal">Aggiungi</ElButton></div><div class="source" v-for="x in c.sources" :key="x.id"><span><b>{{x.name}}</b><small>{{x.lastError||x.lastSyncAt||'Mai sincronizzato'}}</small></span><ElButton text @click="c.removeSource(x.id)">Rimuovi</ElButton></div></template><template v-else-if="section==='radio'"><h2>Radio</h2><p class="muted">Programma l'avvio di una stazione. Il browser può richiedere almeno un'interazione prima di consentire l'audio automatico.</p><div class="schedule-form"><select v-model="scheduleStation"><option value="">Scegli stazione</option><option v-for="x in radio.stations.filter(x=>x.streamUrl)" :key="x.id" :value="x.id">{{x.name}}</option></select><label>Da <input v-model="scheduleStart" type="time"/></label><label>A <input v-model="scheduleEnd" type="time"/></label><div class="days"><label v-for="d in [[1,'L'],[2,'M'],[3,'M'],[4,'G'],[5,'V'],[6,'S'],[0,'D']]" :key="d[0]"><input v-model="scheduleDays" type="checkbox" :value="d[0]"/>{{d[1]}}</label></div><ElButton type="primary" @click="addSchedule">Aggiungi programmazione</ElButton></div><div class="source" v-for="x in radioSchedules.schedules" :key="x.id"><span><b>{{radio.stations.find(s=>s.id===x.stationId)?.name||'Stazione'}}</b><small>{{x.start}}–{{x.end}} · {{x.days.length}} giorni</small></span><ElButton text @click="radioSchedules.remove(x.id)">Rimuovi</ElButton></div></template><template v-else-if="section==='data'"><h2>Dati</h2><p class="muted">Backup JSON schema 4. Le sorgenti calendario restano URL e non vengono incorporate come copie ICS.</p><div class="backup-actions"><ElButton type="primary" @click="backup">Esporta backup</ElButton><label class="import-btn">Importa backup<input type="file" accept="application/json,.json" @change="importBackup"/></label></div></template><template v-else-if="section==='system'"><h2>Sistema</h2><p>Archiviazione persistente: {{persistent===undefined?'non verificata':persistent?'attiva':'non concessa'}}</p><ElButton @click="persist">Richiedi persistenza</ElButton></template><template v-else><h2>Informazioni</h2><p><b>Istante 4.0.0</b><br/>Nuova architettura Vue 3 + TypeScript.</p><p class="muted">Storage schema 4 · build statica · PWA · runtime config esterna.</p></template></section></div></div></template><style scoped>.settings{display:grid;grid-template-columns:230px 1fr;grid-template-rows:auto 1fr;gap:1.2rem}.settings .screen-header{grid-column:1/3}.settings aside{display:grid;align-content:start;gap:.3rem}.settings aside button{border:0;background:transparent;color:var(--text-secondary);text-align:left;padding:.8rem 1rem;border-radius:12px}.settings aside .active{background:rgba(158,205,182,.13);color:var(--accent)}.panel{border-radius:24px;padding:1.4rem;min-height:520px}.panel h2{font-family:var(--font-serif);font-size:1.6rem;font-weight:500;margin-top:0}.row{display:flex;justify-content:space-between;align-items:center;gap:1rem;padding:1rem 0;border-bottom:1px solid rgba(255,255,255,.08)}.field{display:grid;gap:.6rem;margin:1rem 0}.field select{padding:.7rem;border-radius:12px;background:#18211c;color:inherit;border:1px solid var(--glass-border)}.backup-actions{display:flex;gap:.6rem;align-items:center}.import-btn{border:1px solid var(--glass-border);border-radius:999px;padding:.55rem .9rem;cursor:pointer}.import-btn input{display:none}.schedule-form{display:grid;grid-template-columns:2fr 1fr 1fr;gap:.7rem;margin:1rem 0}.schedule-form select,.schedule-form input{background:#18211c;color:inherit;border:1px solid var(--glass-border);border-radius:10px;padding:.6rem}.days{grid-column:1/4;display:flex;gap:.45rem;flex-wrap:wrap}.days label{display:flex;align-items:center;gap:.25rem;padding:.4rem .55rem;border:1px solid var(--glass-border);border-radius:999px}.calendar-add{display:grid;grid-template-columns:1fr 2fr auto;gap:.5rem;margin:1rem 0}.source{display:flex;align-items:center;justify-content:space-between;padding:.8rem 0;border-bottom:1px solid rgba(255,255,255,.08)}.source span{display:grid}.source small{color:var(--text-muted);margin-top:.2rem}@media(max-width:700px){.settings{display:block}.settings .screen-header{display:flex}.settings aside{display:flex;overflow-x:auto;margin-bottom:1rem}.settings aside button{white-space:nowrap}.panel{min-height:0;padding:1rem}.backup-actions{display:flex;gap:.6rem;align-items:center}.import-btn{border:1px solid var(--glass-border);border-radius:999px;padding:.55rem .9rem;cursor:pointer}.import-btn input{display:none}.schedule-form{display:grid;grid-template-columns:2fr 1fr 1fr;gap:.7rem;margin:1rem 0}.schedule-form select,.schedule-form input{background:#18211c;color:inherit;border:1px solid var(--glass-border);border-radius:10px;padding:.6rem}.days{grid-column:1/4;display:flex;gap:.45rem;flex-wrap:wrap}.days label{display:flex;align-items:center;gap:.25rem;padding:.4rem .55rem;border:1px solid var(--glass-border);border-radius:999px}.schedule-form{grid-template-columns:1fr}.days{grid-column:1}.calendar-add{grid-template-columns:1fr}.screen-page{padding:.85rem}}</style>
